SELECT ss.product_id, CASE WHEN ss.revenue >= 3600 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END revenue_bucket, MAX(i.quantity) max_quantity FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.store_id IN (2, 6) GROUP BY ss.product_id, CASE WHEN ss.revenue >= 3600 THEN 'high' WHEN ss.revenue >= 1100 THEN 'mid' ELSE 'low' END HAVING MAX(i.quantity) >= 180
